<template>
  <div class="me-view-body" v-title :data-title="title">
    <div class="me-view-container">
      <main class="me-view-main">

        <article class="me-view-card">
          <header class="me-view-header">
            <h1 class="me-view-title">{{article.title}}</h1>
            <div class="me-view-author">
              <a href="#" class="author-link">
                <img class="me-view-picture" :src="article.author.avatar" alt="作者头像"></img>
              </a>
              <div class="me-view-info">
                <span class="author-name">{{article.author.nickname}}</span>
                <div class="me-view-meta">
                  <span class="meta-item">{{article.createDate | format}}</span>
                  <span class="meta-divider">·</span>
                  <span class="meta-item">阅读 {{article.viewCounts || 0}}</span>
                  <span class="meta-divider">·</span>
                  <span class="meta-item">评论 {{article.commentCounts || 0}}</span>
                </div>
              </div>
              <div class="me-view-actions">
                <el-button
                  v-if="this.article.author.id == this.$store.state.id"
                  @click="editArticle()"
                  class="edit-btn"
                  size="mini"
                  round
                  icon="el-icon-edit">编辑</el-button>
                <el-button
                  v-if="this.$store.state.account"
                  @click="toggleFavorite()"
                  class="favorite-btn"
                  size="mini"
                  round
                  :type="isFavorited ? 'danger' : 'default'"
                  :icon="isFavorited ? 'el-icon-star' : 'el-icon-star-off'">
                  {{ isFavorited ? '已收藏' : '收藏' }}
                </el-button>
              </div>
            </div>
          </header>
          
          <section class="me-view-content">
            <markdown-editor :editor=article.editor></markdown-editor>
          </section>

          <footer class="me-view-footer">
            <div class="me-view-end">
              <el-alert
                title="文章End..."
                type="success"
                center
                :closable="false">
              </el-alert>
            </div>

            <div class="me-view-tags">
              <div class="tag-section">
                <span class="tag-label">标签：</span>
                <el-button 
                  @click="tagOrCategory('tag', t.id)" 
                  size="mini" 
                  type="primary" 
                  v-for="t in article.tags" 
                  :key="t.id" 
                  round plain>{{t.tagname}}</el-button>
              </div>
              <div class="category-section">
                <span class="tag-label">文章分类：</span>
                <el-button 
                  @click="tagOrCategory('category', article.category.id)" 
                  size="mini" 
                  type="primary" 
                  round plain>{{article.category.categoryname}}</el-button>
              </div>
            </div>
          </footer>

          <section class="me-view-comment">
            <div class="me-view-comment-write">
              <div class="comment-input-row">
                <div class="comment-avatar">
                  <a href="#">
                    <img class="me-view-picture" :src="avatar" alt="用户头像"></img>
                  </a>
                </div>
                <div class="comment-input-wrapper">
                  <el-input
                    type="textarea"
                    :autosize="{ minRows: 2, maxRows: 4}"
                    placeholder="发表你的评论..."
                    class="me-view-comment-text"
                    v-model="comment.content"
                    resize="none">
                  </el-input>
                  <button class="comment-submit-btn" @click="publishComment()">评论</button>
                </div>
              </div>
            </div>

            <div class="me-view-comment-title">
              <span>{{article.commentCounts || 0}} 条评论</span>
            </div>

            <div class="comments-list">
              <commment-item
                v-for="(c,index) in comments"
                :comment="c"
                :articleId="article.id"
                :index="index"
                :rootCommentCounts="comments.length"
                @commentCountsIncrement="commentCountsIncrement"
                :key="c.id">
              </commment-item>
            </div>

          </section>

        </article>

        <aside v-if="relatedArticles.length > 0" class="related-articles">
          <h3 class="related-title">📖 相关文章</h3>
          <div class="related-list">
            <div 
              v-for="article in relatedArticles" 
              :key="article.id" 
              class="related-item"
              @click="goToArticle(article.id)"
            >
              <div class="related-tags">
                <span class="related-tag" v-for="tag in (article.tags || []).slice(0, 2)" :key="tag.id">{{ tag.tagname }}</span>
              </div>
              <p class="related-title-text">{{ article.title }}</p>
            </div>
          </div>
        </aside>

      </main>
    </div>
  </div>
</template>

<script>
  import MarkdownEditor from '@/components/markdown/MarkdownEditor'
  import CommmentItem from '@/components/comment/CommentItem'
  import {viewArticle} from '@/api/article'
  import {getCommentsByArticle, publishComment} from '@/api/comment'
  import {getRelatedArticles} from '@/api/recommend'
  import {addFavorite, removeFavorite, getFavoriteStatus} from '@/api/favorite'

  import default_avatar from '@/assets/img/default_avatar.png'

  export default {
    name: 'BlogView',
    created() {
      this.getArticle()
    },
    watch: {
      '$route': 'getArticle'
    },
    data() {
      return {
        article: {
          id: '',
          title: '',
          commentCounts: 0,
          viewCounts: 0,
          summary: '',
          author: {},
          tags: [],
          category:{},
          createDate: '',
          editor: {
            value: '',
            toolbarsFlag: false,
            subfield: false,
            defaultOpen: 'preview'
          }
        },
        comments: [],
        comment: {
          article: {},
          content: ''
        },
        relatedArticles: [],
        isFavorited: false
      }
    },
    computed: {
      avatar() {
        let avatar = this.$store.state.avatar
        if (avatar.length > 0) {
          return avatar
        }
        return default_avatar
      },
      title() {
        return `卫星地面融合网络社区-文章-${this.article.title}`
      }
    },
    methods: {
      tagOrCategory(type, id) {
        this.$router.push({path: `/${type}/${id}`})
      },
      goToArticle(id) {
        this.$router.push({path: `/view/${id}`})
      },
      editArticle() {
        this.$router.push({path: `/write/${this.article.id}`})
      },
      getArticle() {
        let that = this
        viewArticle(that.$route.params.id).then(data => {
          Object.assign(that.article, data.data)
          that.article.editor.value = data.data.body.content
          that.getCommentsByArticle()
          that.getRelatedArticles()
          that.checkFavoriteStatus()
        }).catch(error => {
          if (error !== 'error') {
            that.$message({type: 'error', message: '文章加载失败', showClose: true})
          }
        })
      },
      getRelatedArticles() {
        let that = this
        getRelatedArticles(that.article.id, 6).then(data => {
          if (data && data.data) {
            that.relatedArticles = data.data
          }
        }).catch(error => {
        })
      },
      publishComment() {
        let that = this
        if (!that.comment.content) {
          return;
        }
        that.comment.article.id = that.article.id

        publishComment(that.comment).then(data => {
          that.$message({type: 'success', message: '评论成功', showClose: true})
          that.comments.unshift(data.data)
          that.commentCountsIncrement()
          that.comment.content = ''
        }).catch(error => {
          if (error !== 'error') {
            that.$message({type: 'error', message: '评论失败', showClose: true})
          }
        })
      },
      getCommentsByArticle() {
        let that = this
        getCommentsByArticle(that.article.id).then(data => {
          that.comments = data.data
        }).catch(error => {
          if (error !== 'error') {
            that.$message({type: 'error', message: '评论加载失败', showClose: true})
          }
        })
      },
      commentCountsIncrement() {
        this.article.commentCounts += 1
      },
      toggleFavorite() {
        let that = this
        if (this.isFavorited) {
          removeFavorite(this.article.id).then(data => {
            that.isFavorited = false
            that.$message({type: 'success', message: '取消收藏成功', showClose: true})
          }).catch(error => {
            if (error !== 'error') {
              that.$message({type: 'error', message: '取消收藏失败', showClose: true})
            }
          })
        } else {
          addFavorite(this.article.id).then(data => {
            that.isFavorited = true
            that.$message({type: 'success', message: '收藏成功', showClose: true})
          }).catch(error => {
            if (error !== 'error') {
              that.$message({type: 'error', message: '收藏失败', showClose: true})
            }
          })
        }
      },
      checkFavoriteStatus() {
        let that = this
        if (this.$store.state.account && this.article.id) {
          getFavoriteStatus(this.article.id).then(data => {
            if (data && data.data !== undefined) {
              that.isFavorited = data.data
            }
          }).catch(error => {
            console.log('获取收藏状态失败:', error)
          })
        }
      }
    },
    components: {
      'markdown-editor': MarkdownEditor,
      CommmentItem
    },
    beforeRouteEnter(to, from, next) {
      window.document.body.style.backgroundColor = '#fff';
      next();
    },
    beforeRouteLeave(to, from, next) {
      window.document.body.style.backgroundColor = '#f5f5f5';
      next();
    }
  }
</script>

<style scoped>
  .me-view-body {
    margin: 100px auto 140px;
    padding: 0 20px;
  }

  .me-view-container {
    max-width: 800px;
    margin: 0 auto;
    width: 100%;
  }

  .me-view-main {
    background: #fff;
    border-radius: 8px;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
    overflow: hidden;
  }

  .me-view-card {
    padding: 30px;
  }

  .me-view-header {
    margin-bottom: 30px;
  }

  .me-view-title {
    font-size: 28px;
    font-weight: 700;
    line-height: 1.4;
    color: #1a1a1a;
    margin: 0 0 20px 0;
  }

  .me-view-author {
    display: flex;
    align-items: center;
    position: relative;
    padding-bottom: 20px;
    border-bottom: 1px solid #f0f0f0;
  }

  .me-view-picture {
    width: 48px;
    height: 48px;
    border: 1px solid #ddd;
    border-radius: 50%;
    background-color: #5fb878;
    flex-shrink: 0;
  }

  .me-view-info {
    display: flex;
    flex-direction: column;
    margin-left: 12px;
    flex: 1;
  }

  .author-name {
    font-size: 16px;
    font-weight: 600;
    color: #333;
    margin-bottom: 4px;
  }

  .me-view-meta {
    display: flex;
    align-items: center;
    font-size: 14px;
    color: #969696;
  }

  .meta-item {
    display: flex;
    align-items: center;
  }

  .meta-divider {
    margin: 0 8px;
    color: #ddd;
  }

  .me-view-actions {
    position: absolute;
    right: 0;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    gap: 12px;
  }

  .edit-btn, .favorite-btn {
    flex-shrink: 0;
  }

  .me-view-content {
    margin: 30px 0;
    font-size: 16px;
    line-height: 1.8;
    color: #333;
  }

  .me-view-footer {
    margin-top: 30px;
  }

  .me-view-end {
    margin-bottom: 20px;
  }

  .me-view-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
    padding-left: 8px;
  }

  .tag-section, .category-section {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
  }

  .tag-label {
    font-size: 14px;
    color: #666;
  }

  .me-view-comment {
    margin-top: 40px;
    padding-top: 30px;
    border-top: 1px solid #f0f0f0;
  }

  .me-view-comment-write {
    margin-bottom: 30px;
  }

  .comment-input-row {
    display: flex;
    gap: 12px;
  }

  .comment-avatar {
    flex-shrink: 0;
  }

  .comment-input-wrapper {
    flex: 1;
    position: relative;
  }

  .me-view-comment-text {
    font-size: 15px;
    padding: 12px;
    border-radius: 8px;
    border: 1px solid #e8e8e8;
    resize: none;
  }

  .comment-submit-btn {
    position: absolute;
    right: 12px;
    bottom: 12px;
    padding: 6px 16px;
    background: #1e88e5;
    color: #fff;
    border: none;
    border-radius: 4px;
    font-size: 14px;
    cursor: pointer;
    transition: background 0.3s;
  }

  .comment-submit-btn:hover {
    background: #1976d2;
  }

  .me-view-comment-title {
    font-size: 16px;
    font-weight: 600;
    color: #333;
    margin-bottom: 20px;
    padding-bottom: 15px;
    border-bottom: 1px solid #f0f0f0;
  }

  .comments-list {
    margin-top: 20px;
  }

  .related-articles {
    margin-top: 30px;
    padding: 25px 30px;
    background: #fafafa;
  }

  .related-title {
    font-size: 18px;
    font-weight: bold;
    color: #1e88e5;
    margin-bottom: 15px;
    padding-left: 10px;
    border-left: 4px solid #1e88e5;
  }

  .related-list {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 15px;
  }

  .related-item {
    padding: 15px;
    background: #fff;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    border: 1px solid #e8e8e8;
  }

  .related-item:hover {
    border-color: #1e88e5;
    box-shadow: 0 2px 8px rgba(30, 136, 229, 0.15);
  }

  .related-tags {
    margin-bottom: 8px;
  }

  .related-tag {
    display: inline-block;
    font-size: 12px;
    color: #1e88e5;
    background: #e3f2fd;
    padding: 2px 8px;
    border-radius: 4px;
    margin-right: 5px;
  }

  .related-title-text {
    font-size: 14px;
    color: #333;
    margin: 0;
    line-height: 1.5;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  @media screen and (max-width: 767px) {
    .me-view-body {
      margin: 80px auto 120px;
      padding: 0 15px;
    }

    .me-view-card {
      padding: 20px;
    }

    .me-view-title {
      font-size: 22px;
      line-height: 1.4;
    }

    .me-view-author {
      flex-wrap: wrap;
      gap: 10px;
    }

    .me-view-info {
      margin-left: 10px;
      flex: auto;
    }

    .author-name {
      font-size: 15px;
    }

    .me-view-meta {
      font-size: 13px;
    }

    .edit-btn {
      position: static;
      transform: none;
      margin-top: 10px;
    }

    .me-view-content {
      margin: 20px 0;
      font-size: 15px;
    }

    .me-view-tags {
      flex-direction: column;
      gap: 10px;
    }

    .tag-section, .category-section {
      flex-wrap: wrap;
    }

    .comment-input-row {
      flex-direction: column;
    }

    .comment-submit-btn {
      position: static;
      margin-top: 12px;
      width: 100%;
      padding: 12px;
    }

    .related-list {
      grid-template-columns: 1fr;
    }

    .related-item {
      padding: 12px;
    }
  }

  @media screen and (min-width: 768px) and (max-width: 1024px) {
    .me-view-body {
      margin: 90px auto 130px;
      padding: 0 20px;
    }

    .me-view-container {
      max-width: 100%;
    }

    .me-view-card {
      padding: 25px;
    }

    .me-view-title {
      font-size: 24px;
    }

    .related-list {
      grid-template-columns: repeat(2, 1fr);
    }
  }

  @media screen and (min-width: 1025px) {
    .me-view-container {
      max-width: 800px;
    }
  }
</style>

<style>
  .v-show-content {
    padding: 8px 25px 15px 0px !important;
  }

  .v-note-wrapper .v-note-panel {
    box-shadow: none !important;
  }

  .v-note-wrapper .v-note-panel .v-note-show .v-show-content, 
  .v-note-wrapper .v-note-panel .v-note-show .v-show-content-html {
    background: #fff !important;
  }
</style>


