import request from '@/request'

export function addFavorite(articleId) {
  return request({
    url: `/favorites/${articleId}`,
    method: 'post'
  })
}

export function removeFavorite(articleId) {
  return request({
    url: `/favorites/${articleId}`,
    method: 'delete'
  })
}

export function getFavoriteStatus(articleId) {
  return request({
    url: `/favorites/${articleId}/status`,
    method: 'get'
  })
}

export function getFavorites() {
  return request({
    url: '/favorites',
    method: 'get'
  })
}

export function getFavoriteCount() {
  return request({
    url: '/favorites/count',
    method: 'get'
  })
}


